// Adapted from ww37 src/services/reservationService.ts:66-121 @ 0d0f32c
// (listReservations + a reduced createHold; the in-memory repository filter from
// src/repositories/inMemoryInventoryRepository.ts:128-140 and the role helper from
// src/lib/auth/roles.ts:26-28 inlined so the service runs standalone).
export function canViewAllReservationAction(role) {
  return role === 'owner' || role === 'manager';
}

export class InMemoryRepository {
  constructor() {
    this.reservations = new Map();
    this.seq = 0;
  }
  async createReservation(r) {
    const row = { id: `res-${++this.seq}`, ...r };
    this.reservations.set(row.id, row);
    return { ...row };
  }
  async listReservations(filter) {
    return [...this.reservations.values()]
      .filter((reservation) => {
        if (filter?.createdByUserId && reservation.createdByUserId !== filter.createdByUserId) {
          return false;
        }
        return true;
      })
      .map((r) => ({ ...r }));
  }
}

export function createReservationService(repository) {
  return {
    async listReservations(session) {
      if (canViewAllReservationAction(session.role)) {
        return repository.listReservations();
      }

      return repository.listReservations({
        createdByUserId: session.userId,
      });
    },

    async createHold(input, session) {
      if (session.role === 'viewer') {
        throw new Error('View-only users cannot create stock holds.');
      }
      return repository.createReservation({
        itemId: input.itemId,
        quantity: input.quantity,
        reason: input.reason,
        status: 'active',
        createdByUserId: session.userId,
        createdByUserName: session.displayName,
      });
    },
  };
}

