// Adapted from ww37 src/lib/auth/session.ts:8-30 @ 0d0f32c (types removed; isUserRole
// from src/lib/auth/roles.ts:8-16 inlined so the module runs standalone).
export const userRoles = ['owner', 'manager', 'clerk', 'viewer'];

export function isUserRole(value) {
  return Boolean(value && userRoles.includes(value));
}

export function getSessionFromRequest(request) {
  const userId = request.headers.get('x-user-id')?.trim();
  const displayName = request.headers.get('x-user-name')?.trim() || 'Unnamed User';
  const roleHeader = request.headers.get('x-user-role');

  if (!userId || !isUserRole(roleHeader)) {
    return null;
  }

  return {
    userId,
    displayName,
    role: roleHeader,
  };
}
